#![allow(non_snake_case, unused_variables, unused_mut)]

use arcstr::ArcStr;
use metamodelica::{List, OrderedFloat, Result};
use openmodelica_error::ErrorTypes;
use openmodelica_frontend_types::Values;
use openmodelica_result_files::scripting::{self, Messages, Severity};
use openmodelica_util::Error;

struct Sink(Result<()>);

impl Messages for Sink {
    fn add(&mut self, severity: Severity, format: &str, tokens: &[&str]) {
        if self.0.is_err() {
            return;
        }
        let message = ErrorTypes::Message {
            id: -1,
            ty: ErrorTypes::MessageType::SCRIPTING,
            severity: match severity {
                Severity::Error => ErrorTypes::Severity::ERROR,
                Severity::Warning => ErrorTypes::Severity::WARNING,
                Severity::Notification => ErrorTypes::Severity::NOTIFICATION,
            },
            message: ArcStr::from(format),
        };
        self.0 = Error::addMessage(message, List::from_iter(tokens.iter().map(|t| ArcStr::from(*t))));
    }
}

fn reporting<T>(f: impl FnOnce(&mut dyn Messages) -> T) -> Result<T> {
    let mut sink = Sink(Ok(()));
    let res = f(&mut sink);
    sink.0.map(|()| res)
}

fn strings(vars: &List<ArcStr>) -> Vec<String> {
    vars.as_ref().into_iter().map(|v| v.to_string()).collect()
}

fn list(strings: Vec<String>) -> List<ArcStr> {
    List::from_iter(strings.into_iter().map(ArcStr::from))
}

/// `ValuesMake.makeArray`: the new outer dimension goes first.
fn make_array(vals: Vec<metamodelica::Ref<Values::Value>>) -> metamodelica::Ref<Values::Value> {
    let n = vals.len() as i32;
    let inner_dims: List<i32> = match vals.first().map(|v| &**v) {
        Some(Values::ARRAY { dimLst, .. }) => dimLst.clone(),
        _ => metamodelica::nil(),
    };
    metamodelica::Ref::new(Values::ARRAY {
        valueLst: List::from_iter(vals),
        dimLst: metamodelica::cons(n, inner_dims),
    })
}

pub fn val(mut filename: ArcStr, mut varname: ArcStr, mut timeStamp: metamodelica::Real) -> Result<metamodelica::Real> {
    reporting(|m| OrderedFloat(scripting::val(m, &filename, &varname, timeStamp.into_inner())))
}

pub fn readVariables(
    mut filename: ArcStr,
    mut readParameters: bool,
    mut openmodelicaStyle: bool,
) -> Result<metamodelica::List<ArcStr>> {
    reporting(|m| {
        list(scripting::read_variables(
            m,
            &filename,
            readParameters,
            openmodelicaStyle,
        ))
    })
}

pub fn readDataset(
    mut filename: ArcStr,
    mut vars: metamodelica::List<ArcStr>,
    mut dimsize: i32,
) -> Result<metamodelica::Ref<Values::Value>> {
    let rows =
        reporting(|m| scripting::read_dataset(m, &filename, &strings(&vars), dimsize))?.ok_or("readDataset failed")?;
    let rows = rows
        .into_iter()
        .map(|row| {
            make_array(
                row.into_iter()
                    .map(|x| metamodelica::Ref::new(Values::REAL { real: OrderedFloat(x) }))
                    .collect(),
            )
        })
        .collect();
    Ok(make_array(rows))
}

pub fn readSimulationResultSize(mut filename: ArcStr) -> Result<i32> {
    reporting(|m| scripting::read_size(m, &filename))
}

pub fn close() {
    scripting::close();
}

pub fn cmpSimulationResults(
    mut runningTestsuite: bool,
    mut filename: ArcStr,
    mut reffilename: ArcStr,
    mut logfilename: ArcStr,
    mut refTol: metamodelica::Real,
    mut absTol: metamodelica::Real,
    mut vars: metamodelica::List<ArcStr>,
) -> Result<metamodelica::List<ArcStr>> {
    let res = reporting(|m| {
        scripting::compare(
            m,
            runningTestsuite,
            &filename,
            &reffilename,
            &logfilename,
            refTol.into_inner(),
            absTol.into_inner(),
            &strings(&vars),
        )
    })?;
    Ok(list(res.ok_or("compareSimulationResults failed")?))
}

pub fn deltaSimulationResults(
    mut filename: ArcStr,
    mut reffilename: ArcStr,
    mut method: ArcStr,
    mut vars: metamodelica::List<ArcStr>,
) -> Result<metamodelica::Real> {
    reporting(|m| OrderedFloat(scripting::delta(m, &filename, &reffilename, &method, &strings(&vars))))
}

pub fn diffSimulationResults(
    mut runningTestsuite: bool,
    mut filename: ArcStr,
    mut reffilename: ArcStr,
    mut prefix: ArcStr,
    mut refTol: metamodelica::Real,
    mut relTolDiffMaxMin: metamodelica::Real,
    mut rangeDelta: metamodelica::Real,
    mut vars: metamodelica::List<ArcStr>,
    mut keepEqualResults: bool,
) -> Result<(bool, metamodelica::List<ArcStr>)> {
    let (success, res) = reporting(|m| {
        scripting::diff(
            m,
            runningTestsuite,
            &filename,
            &reffilename,
            &prefix,
            refTol.into_inner(),
            relTolDiffMaxMin.into_inner(),
            rangeDelta.into_inner(),
            &strings(&vars),
            keepEqualResults,
        )
    })?;
    Ok((success, list(res)))
}

pub fn diffSimulationResultsHtml(
    mut runningTestsuite: bool,
    mut filename: ArcStr,
    mut reffilename: ArcStr,
    mut refTol: metamodelica::Real,
    mut relTolDiffMaxMin: metamodelica::Real,
    mut rangeDelta: metamodelica::Real,
    mut var: ArcStr,
) -> Result<ArcStr> {
    let html = reporting(|m| {
        scripting::diff_html(
            m,
            runningTestsuite,
            &var,
            &filename,
            &reffilename,
            refTol.into_inner(),
            relTolDiffMaxMin.into_inner(),
            rangeDelta.into_inner(),
        )
    })?;
    Ok(ArcStr::from(html.ok_or("diffSimulationResultsHtml failed")?))
}

pub fn filterSimulationResults(
    mut inFile: ArcStr,
    mut outFile: ArcStr,
    mut vars: metamodelica::List<ArcStr>,
    mut numberOfIntervals: i32,
    mut removeDescription: bool,
    mut hintReadAllVars: bool,
) -> Result<bool> {
    reporting(|m| {
        scripting::filter(
            m,
            &inFile,
            &outFile,
            &strings(&vars),
            numberOfIntervals,
            removeDescription,
        )
    })
}
